import * as React from "react";
import { Slot } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/cn";
import { Spinner } from "./spinner";

export const buttonVariants = cva(
  [
    "relative inline-flex select-none items-center justify-center gap-2 whitespace-nowrap font-medium",
    "transition-[transform,box-shadow,background-color,color] duration-[var(--dur-micro)] ease-[var(--ease-out)]",
    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus",
    "disabled:pointer-events-none disabled:opacity-50 aria-busy:pointer-events-none",
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ],
  {
    variants: {
      variant: {
        primary:
          "vx-glass border border-[color:var(--btn-border)] bg-[color:var(--btn-bg)] [background-image:var(--btn-image)] text-accent-ink shadow-key-accent hover:translate-y-[var(--lift)] hover:brightness-110 active:translate-y-[var(--press)] active:shadow-key-press",
        secondary:
          "vx-glass border border-[color:var(--key-border)] bg-key-face text-ink shadow-key hover:translate-y-[var(--lift)] hover:bg-paper-2 active:translate-y-[var(--press)] active:shadow-key-press",
        soft: "bg-accent-wash text-accent-wash-ink hover:bg-accent-wash/70",
        outline: "border border-[color:var(--key-border)] text-ink hover:bg-paper-2",
        ghost: "text-ink-2 hover:bg-paper-3 hover:text-ink",
        danger:
          "border border-[color:var(--btn-border)] bg-danger [background-image:var(--btn-danger-image)] text-white shadow-key-danger hover:translate-y-[var(--lift)] hover:brightness-110 active:translate-y-[var(--press)] active:shadow-key-press",
        link: "h-auto px-0 text-accent underline-offset-4 decoration-rule-2 hover:underline hover:decoration-accent",
      },
      size: {
        xs: "h-7 rounded-sm px-2.5 text-xs",
        sm: "h-8 rounded-input px-3 text-sm",
        md: "h-9 rounded-input px-4 text-sm",
        lg: "h-11 rounded-card px-5 text-base",
        icon: "size-9 rounded-input",
        "icon-sm": "size-8 rounded-input",
      },
    },
    defaultVariants: { variant: "primary", size: "md" },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /** Render the child element instead of a button, keeping the styles. */
  asChild?: boolean;
  /** Show a spinner and block interaction. */
  loading?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild, loading, children, disabled, ...props }, ref) => {
    const Comp = asChild ? Slot.Root : "button";
    return (
      <Comp
        ref={ref}
        data-slot="button"
        className={cn(buttonVariants({ variant, size }), className)}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        {...props}
      >
        {asChild ? (
          children
        ) : (
          <>
            {loading && <Spinner className="size-4" />}
            {children}
          </>
        )}
      </Comp>
    );
  },
);
Button.displayName = "Button";

import * as React from "react";
import { ToggleGroup } from "radix-ui";
import { cn } from "@/lib/cn";

/**
 * Places a pill under the active item of a list and slides it on change. The pill is positioned
 * instantly and animated with a transform from where it was, so width and left never animate.
 */
export function useSlidingPill(list: React.RefObject<HTMLElement | null>, selector: string, active: unknown) {
  const pill = React.useRef<HTMLSpanElement>(null);
  const last = React.useRef<{ x: number; w: number } | null>(null);
  React.useLayoutEffect(() => {
    const l = list.current;
    const p = pill.current;
    if (!l || !p) return;
    const place = (animate: boolean) => {
      const a = l.querySelector<HTMLElement>(selector);
      if (!a) {
        p.style.opacity = "0";
        return;
      }
      const { offsetLeft: x, offsetTop: y, offsetWidth: w, offsetHeight: h } = a;
      Object.assign(p.style, { opacity: "1", left: `${x}px`, top: `${y}px`, width: `${w}px`, height: `${h}px` });
      const prev = last.current;
      last.current = { x, w };
      if (!animate || !prev || (prev.x === x && prev.w === w) || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
      p.style.transition = "none";
      p.style.transform = `translateX(${prev.x - x}px) scaleX(${prev.w / w})`;
      void p.offsetWidth;
      p.style.transition = "";
      p.style.transform = "";
    };
    place(true);
    const ro = new ResizeObserver(() => place(false));
    ro.observe(l);
    return () => ro.disconnect();
  }, [list, selector, active]);
  return pill;
}

/** The pill itself: a raised key that slides between options. */
export const pillClass =
  "pointer-events-none absolute left-0 top-0 origin-left rounded-[var(--pill-radius)] bg-key-face opacity-0 shadow-key transition-transform duration-200 ease-[var(--ease-out)]";

export interface SegmentedProps {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  options: { value: string; label: React.ReactNode; disabled?: boolean }[];
  size?: "sm" | "md";
  className?: string;
  "aria-label"?: string;
}

/** A single-choice control: options sit on a tray and a raised pill slides to the chosen one. */
export function Segmented({ value, defaultValue, onValueChange, options, size = "md", className, ...rest }: SegmentedProps) {
  const [inner, setInner] = React.useState(defaultValue ?? options[0]?.value);
  const current = value ?? inner;
  const list = React.useRef<HTMLDivElement>(null);
  const pill = useSlidingPill(list, '[data-state="on"]', current);
  return (
    <ToggleGroup.Root
      ref={list}
      type="single"
      value={current}
      onValueChange={(v) => {
        if (!v) return;
        setInner(v);
        onValueChange?.(v);
      }}
      className={cn("vx-glass relative inline-flex w-fit items-center gap-0.5 rounded-input border border-tray-border bg-tray p-1", className)}
      {...rest}
    >
      <span ref={pill} aria-hidden className={pillClass} />
      {options.map((o) => (
        <ToggleGroup.Item
          key={o.value}
          value={o.value}
          disabled={o.disabled}
          className={cn(
            "relative z-10 inline-flex items-center justify-center gap-1.5 rounded-[var(--pill-radius)] font-medium text-muted",
            "transition-colors duration-[var(--dur-micro)] hover:text-ink",
            "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus disabled:opacity-50 [&_svg]:size-4",
            "data-[state=on]:text-ink",
            size === "md" ? "h-7 px-3 text-sm" : "h-6 px-2 text-xs",
          )}
        >
          {o.label}
        </ToggleGroup.Item>
      ))}
    </ToggleGroup.Root>
  );
}

import * as React from "react";
import { DropdownMenu as Menu } from "radix-ui";
import { Check, ChevronRight } from "lucide-react";
import { cn } from "@/lib/cn";
import { menuItem, menuLabel, menuPanel, menuSeparator } from "./menu-styles";

export const DropdownMenu = Menu.Root;
export const DropdownMenuTrigger = Menu.Trigger;
export const DropdownMenuGroup = Menu.Group;
export const DropdownMenuSub = Menu.Sub;
export const DropdownMenuRadioGroup = Menu.RadioGroup;

const panel = menuPanel;
const item = menuItem;

export function DropdownMenuContent({ className, sideOffset = 6, ...props }: React.ComponentProps<typeof Menu.Content>) {
  return (
    <Menu.Portal>
      <Menu.Content sideOffset={sideOffset} className={cn(panel, className)} {...props} />
    </Menu.Portal>
  );
}

export function DropdownMenuItem({
  className,
  shortcut,
  destructive,
  children,
  ...props
}: React.ComponentProps<typeof Menu.Item> & { shortcut?: string; destructive?: boolean }) {
  return (
    <Menu.Item
      className={cn(item, destructive && "text-danger data-[highlighted]:bg-danger-wash [&_svg]:text-danger", className)}
      {...props}
    >
      {children}
      {shortcut && <span className="ml-auto font-mono text-xs text-muted">{shortcut}</span>}
    </Menu.Item>
  );
}

export function DropdownMenuCheckboxItem({ className, children, ...props }: React.ComponentProps<typeof Menu.CheckboxItem>) {
  return (
    <Menu.CheckboxItem className={cn(item, "pl-9", className)} {...props}>
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Menu.ItemIndicator>
          <Check className="!text-accent" />
        </Menu.ItemIndicator>
      </span>
      {children}
    </Menu.CheckboxItem>
  );
}

export function DropdownMenuRadioItem({ className, children, ...props }: React.ComponentProps<typeof Menu.RadioItem>) {
  return (
    <Menu.RadioItem className={cn(item, "pl-9", className)} {...props}>
      <span className="absolute left-2.5 flex size-4 items-center justify-center">
        <Menu.ItemIndicator>
          <span className="block size-1.5 rounded-full bg-accent" />
        </Menu.ItemIndicator>
      </span>
      {children}
    </Menu.RadioItem>
  );
}

export function DropdownMenuLabel({ className, ...props }: React.ComponentProps<typeof Menu.Label>) {
  return <Menu.Label className={cn(menuLabel, className)} {...props} />;
}

export function DropdownMenuSeparator({ className, ...props }: React.ComponentProps<typeof Menu.Separator>) {
  return <Menu.Separator className={cn(menuSeparator, className)} {...props} />;
}

export function DropdownMenuSubTrigger({ className, children, ...props }: React.ComponentProps<typeof Menu.SubTrigger>) {
  return (
    <Menu.SubTrigger className={cn(item, "data-[state=open]:bg-paper-3", className)} {...props}>
      {children}
      <ChevronRight className="ml-auto" />
    </Menu.SubTrigger>
  );
}

export function DropdownMenuSubContent({ className, ...props }: React.ComponentProps<typeof Menu.SubContent>) {
  return (
    <Menu.Portal>
      <Menu.SubContent className={cn(panel, className)} {...props} />
    </Menu.Portal>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";

export const fieldBase = [
  "vx-glass w-full rounded-input border border-field-border bg-field text-sm text-ink shadow-field",
  "placeholder:text-muted/80 outline-none",
  "transition-[border-color,box-shadow] duration-[var(--dur-micro)]",
  "hover:field-hover",
  "focus-visible:field-focus focus-visible:outline-none",
  "disabled:cursor-not-allowed disabled:bg-paper-2 disabled:opacity-60",
  "aria-invalid:border-danger aria-invalid:focus-visible:shadow-[0_0_0_3px_color-mix(in_oklab,var(--danger)_22%,transparent)]",
].join(" ");

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  /** Icon or text placed before the value. */
  leading?: React.ReactNode;
  /** Icon, text or a button placed after the value. */
  trailing?: React.ReactNode;
  inputSize?: "sm" | "md" | "lg";
}

const sizes = { sm: "h-8 px-2.5", md: "h-9 px-3", lg: "h-11 px-3.5 text-base" };

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, leading, trailing, inputSize = "md", ...props }, ref) => {
    if (!leading && !trailing) {
      return <input ref={ref} className={cn(fieldBase, sizes[inputSize], className)} {...props} />;
    }
    return (
      <div className={cn("relative flex items-center", className)}>
        {leading && (
          <span className="pointer-events-none absolute left-3 flex items-center text-muted [&_svg]:size-4">
            {leading}
          </span>
        )}
        <input
          ref={ref}
          className={cn(fieldBase, sizes[inputSize], leading && "pl-9", trailing && "pr-10")}
          {...props}
        />
        {trailing && (
          <span className="absolute right-2 flex items-center text-muted [&_svg]:size-4">{trailing}</span>
        )}
      </div>
    );
  },
);
Input.displayName = "Input";

import * as React from "react";
import { cn } from "@/lib/cn";
import { fieldBase } from "./input";

export const Textarea = React.forwardRef<HTMLTextAreaElement, React.TextareaHTMLAttributes<HTMLTextAreaElement>>(
  ({ className, ...props }, ref) => (
    <textarea ref={ref} className={cn(fieldBase, "min-h-24 resize-y px-3 py-2 leading-6", className)} {...props} />
  ),
);
Textarea.displayName = "Textarea";

import * as React from "react";
import { Select as SelectPrimitive } from "radix-ui";
import { Check, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/cn";
import { menuItem, menuLabel, menuPanel, menuSeparator } from "./menu-styles";

export const Select = SelectPrimitive.Root;
export const SelectGroup = SelectPrimitive.Group;
export const SelectValue = SelectPrimitive.Value;

export function SelectTrigger({ className, children, ...props }: React.ComponentProps<typeof SelectPrimitive.Trigger>) {
  return (
    <SelectPrimitive.Trigger
      className={cn(
        "flex h-9 w-full items-center justify-between gap-2 rounded-input border border-field-border bg-field px-3 text-sm text-ink shadow-field vx-glass",
        "hover:field-hover focus-visible:field-focus focus-visible:outline-none",
        "data-[placeholder]:text-muted disabled:cursor-not-allowed disabled:opacity-50 [&>span]:truncate",
        className,
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon asChild>
        <ChevronsUpDown className="size-4 shrink-0 text-muted" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
}

export function SelectContent({
  className,
  children,
  position = "popper",
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Content>) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        position={position}
        sideOffset={6}
        className={cn(
          menuPanel, "relative max-h-[min(var(--radix-select-content-available-height),340px)] min-w-[8rem]",
          position === "popper" && "w-[var(--radix-select-trigger-width)]",
          className,
        )}
        {...props}
      >
        <SelectPrimitive.Viewport>{children}</SelectPrimitive.Viewport>
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
}

export function SelectLabel({ className, ...props }: React.ComponentProps<typeof SelectPrimitive.Label>) {
  return <SelectPrimitive.Label className={cn(menuLabel, className)} {...props} />;
}

export function SelectItem({ className, children, ...props }: React.ComponentProps<typeof SelectPrimitive.Item>) {
  return (
    <SelectPrimitive.Item
      className={cn(
        menuItem, "w-full pr-9",
        className,
      )}
      {...props}
    >
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
      <span className="absolute right-2.5 flex size-4 items-center justify-center [&_svg]:!text-accent">
        <SelectPrimitive.ItemIndicator>
          <Check className="size-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
    </SelectPrimitive.Item>
  );
}

export function SelectSeparator({ className, ...props }: React.ComponentProps<typeof SelectPrimitive.Separator>) {
  return <SelectPrimitive.Separator className={cn(menuSeparator, className)} {...props} />;
}

import * as React from "react";
import { Checkbox as CheckboxPrimitive } from "radix-ui";
import { Check, Minus } from "lucide-react";
import { cn } from "@/lib/cn";

export const Checkbox = React.forwardRef<
  React.ElementRef<typeof CheckboxPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>
>(({ className, ...props }, ref) => (
  <CheckboxPrimitive.Root
    ref={ref}
    className={cn(
      "peer grid size-4 shrink-0 place-items-center rounded-[calc(4px*var(--radius-factor))] border border-[color:var(--control-border)] bg-[color:var(--control)] shadow-[var(--elev-control)]",
      "transition-[background-color,border-color,box-shadow] duration-[var(--dur-micro)] hover:border-muted",
      "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus",
      "data-[state=checked]:border-transparent data-[state=checked]:bg-accent data-[state=checked]:[background-image:var(--control-on-image)] data-[state=checked]:shadow-[var(--elev-control-on)] data-[state=checked]:text-accent-ink",
      "data-[state=indeterminate]:border-transparent data-[state=indeterminate]:bg-accent data-[state=indeterminate]:[background-image:var(--control-on-image)] data-[state=indeterminate]:shadow-[var(--elev-control-on)] data-[state=indeterminate]:text-accent-ink",
      "disabled:cursor-not-allowed disabled:opacity-50",
      className,
    )}
    {...props}
  >
    <CheckboxPrimitive.Indicator className="grid place-items-center">
      {props.checked === "indeterminate" ? (
        <Minus className="size-3" strokeWidth={3} />
      ) : (
        <Check className="size-3" strokeWidth={3.5} />
      )}
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
));
Checkbox.displayName = "Checkbox";

import * as React from "react";
import { RadioGroup as RadioGroupPrimitive } from "radix-ui";
import { cn } from "@/lib/cn";

export function RadioGroup({ className, ...props }: React.ComponentProps<typeof RadioGroupPrimitive.Root>) {
  return <RadioGroupPrimitive.Root className={cn("grid gap-2.5", className)} {...props} />;
}

export function RadioGroupItem({ className, ...props }: React.ComponentProps<typeof RadioGroupPrimitive.Item>) {
  return (
    <RadioGroupPrimitive.Item
      className={cn(
        "peer grid size-4 shrink-0 place-items-center rounded-full border border-[color:var(--control-border)] bg-[color:var(--control)] shadow-[var(--elev-control)]",
        "transition-[background-color,border-color,box-shadow] duration-[var(--dur-micro)] hover:border-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus",
        "data-[state=checked]:border-transparent data-[state=checked]:bg-accent data-[state=checked]:[background-image:var(--control-on-image)] data-[state=checked]:shadow-[var(--elev-control-on)]",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
      {...props}
    >
      <RadioGroupPrimitive.Indicator className="block size-1.5 rounded-full bg-accent-ink" />
    </RadioGroupPrimitive.Item>
  );
}

/** A bordered, selectable card that wraps a radio. */
export function RadioCard({
  value,
  title,
  description,
  className,
}: {
  value: string;
  title: React.ReactNode;
  description?: React.ReactNode;
  className?: string;
}) {
  return (
    <label
      className={cn(
        "vx-glass flex cursor-pointer items-start gap-3 rounded-card border border-card-border bg-card p-3.5 shadow-card",
        "transition-[border-color,background-color] duration-[var(--dur-micro)] hover:border-rule-2",
        "has-[[data-state=checked]]:border-accent has-[[data-state=checked]]:bg-accent-wash/50",
        className,
      )}
    >
      <RadioGroupItem value={value} className="mt-0.5" />
