import * as React from "react";
import { Popover as PopoverPrimitive } from "radix-ui";
import { Check, ChevronsUpDown, Search } from "lucide-react";
import { cn } from "@/lib/cn";
import { menuCheck, menuItem, menuLabel, menuPanel } from "./menu-styles";

export interface ComboboxOption {
  value: string;
  label: string;
  description?: string;
}

export interface ComboboxProps {
  options: ComboboxOption[];
  value?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  className?: string;
  "aria-label"?: string;
}

/** A select with a search field, for long option lists. */
export function Combobox({
  options,
  value,
  onValueChange,
  placeholder = "Select…",
  searchPlaceholder = "Search…",
  emptyText = "Nothing found.",
  className,
  ...rest
}: ComboboxProps) {
  const [open, setOpen] = React.useState(false);
  const [inner, setInner] = React.useState(value);
  const [q, setQ] = React.useState("");
  const [active, setActive] = React.useState(0);
  const current = value ?? inner;
  const selected = options.find((o) => o.value === current);
  const list = options.filter((o) => o.label.toLowerCase().includes(q.toLowerCase()));

  const pick = (o: ComboboxOption) => {
    setInner(o.value);
    onValueChange?.(o.value);
    setOpen(false);
    setQ("");
  };

  return (
    <PopoverPrimitive.Root open={open} onOpenChange={(o) => { setOpen(o); if (o) setActive(Math.max(0, list.indexOf(selected!))); }}>
      <PopoverPrimitive.Trigger
        role="combobox"
        aria-expanded={open}
        aria-label={rest["aria-label"]}
        className={cn(
          "flex h-9 w-full items-center justify-between gap-2 rounded-input border border-field-border bg-field px-3 text-sm shadow-field vx-glass",
          "hover:field-hover focus-visible:field-focus focus-visible:outline-none",
          className,
        )}
      >
        <span className={cn("truncate", !selected && "text-muted")}>{selected?.label ?? placeholder}</span>
        <ChevronsUpDown className="size-4 shrink-0 text-muted" />
      </PopoverPrimitive.Trigger>
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content
          align="start"
          sideOffset={6}
          className={cn(menuPanel, "w-[var(--radix-popover-trigger-width)] min-w-56 p-0")}
        >
          <div className="flex items-center gap-2 border-b border-rule px-3">
            <Search className="size-4 text-muted" />
            <input
              autoFocus
              value={q}
              onChange={(e) => { setQ(e.target.value); setActive(0); }}
              onKeyDown={(e) => {
                if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => Math.min(a + 1, list.length - 1)); }
                if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => Math.max(a - 1, 0)); }
                if (e.key === "Enter" && list[active]) { e.preventDefault(); pick(list[active]); }
              }}
              placeholder={searchPlaceholder}
              aria-label={searchPlaceholder}
              className="h-10 flex-1 bg-transparent text-sm outline-none placeholder:text-muted"
            />
          </div>
          <ul role="listbox" className="max-h-64 overflow-y-auto p-1.5">
            {list.length === 0 && <li className="px-3 py-5 text-center text-sm text-muted">{emptyText}</li>}
            {list.map((o, i) => (
              <li
                key={o.value}
                role="option"
                aria-selected={o.value === current}
                onMouseMove={() => setActive(i)}
                onClick={() => pick(o)}
                data-active={i === active}
                className={menuItem}
              >
                <span className="grid flex-1">
                  <span>{o.label}</span>
                  {o.description && <span className="text-xs text-muted">{o.description}</span>}
                </span>
                {o.value === current && <Check className={menuCheck} />}
              </li>
            ))}
          </ul>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

import * as React from "react";
import { cn } from "@/lib/cn";

export interface InputOTPProps {
  length?: number;
  value?: string;
  onChange?: (value: string) => void;
  /** Called once every cell is filled. */
  onComplete?: (value: string) => void;
  /** Insert a gap after this many cells, e.g. 3 for 123-456. */
  groupSize?: number;
  disabled?: boolean;
  invalid?: boolean;
  className?: string;
  "aria-label"?: string;
}

/** One-time code entry: digits only, auto-advance, paste the full code. */
export function InputOTP({ length = 6, value, onChange, onComplete, groupSize, disabled, invalid, className, ...rest }: InputOTPProps) {
  const [inner, setInner] = React.useState("");
  const [focused, setFocused] = React.useState(false);
  const code = (value ?? inner).slice(0, length);
  const ref = React.useRef<HTMLInputElement>(null);

  const set = (next: string) => {
    const clean = next.replace(/\D/g, "").slice(0, length);
    setInner(clean);
    onChange?.(clean);
    if (clean.length === length) onComplete?.(clean);
  };

  return (
    <div className={cn("relative inline-flex items-center gap-2", className)} onClick={() => ref.current?.focus()}>
      <input
        ref={ref}
        value={code}
        onChange={(e) => set(e.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        inputMode="numeric"
        autoComplete="one-time-code"
        maxLength={length}
        disabled={disabled}
        aria-label={rest["aria-label"] ?? "One-time code"}
        aria-invalid={invalid || undefined}
        className="absolute inset-0 cursor-text opacity-0 disabled:cursor-not-allowed"
      />
      {Array.from({ length }).map((_, i) => {
        const active = focused && (i === code.length || (i === length - 1 && code.length === length));
        return (
          <React.Fragment key={i}>
            {groupSize && i > 0 && i % groupSize === 0 && <span aria-hidden className="h-px w-3 bg-rule-2" />}
            <span
              aria-hidden
              className={cn(
                "vx-glass grid size-11 place-items-center rounded-input border bg-field font-mono text-lg text-ink shadow-field",
                "transition-[border-color,box-shadow] duration-[var(--dur-micro)]",
                invalid ? "border-danger" : active ? "field-focus" : "border-field-border",
                disabled && "bg-paper-2 opacity-60",
              )}
            >
              {code[i] ?? (active ? <span className="vx-caret h-5 w-px bg-ink" /> : "")}
            </span>
          </React.Fragment>
        );
      })}
    </div>
  );
}

